(1817429, 248780, 36361, '<td valign="top">looks a bit over sharpened</td>', 'looks a bit over sharpened', '2005-10-27 09:06:27.000000', NULL, 1),
(1817443, 246875, 25355, '<td valign="top">Great effect, vibrant colours. Well done. 9</td>', 'Great effect, vibrant colours. Well done. 9', '2005-10-27 09:16:47.000000', NULL, 1),
(1817446, 249226, 25355, '<td valign="top">Excellent scene of a desolate spo, and good framing of the distant tree. I would''ve liked to have seen this in colour. I''ll give you a 10 anyway.</td>', 'Excellent scene of a desolate spo, and good framing of the distant tree. I would''ve liked to have seen this in colour. I''ll give you a 10 anyway.', '2005-10-27 09:19:13.000000', NULL, 1),
(1817448, 249229, 25355, '<td valign="top">Lovely candid portrait; just a wee shame about the odd shapes in the background. Good luck.</td>', 'Lovely candid portrait; just a wee shame about the odd shapes in the background. Good luck.', '2005-10-27 09:20:18.000000', NULL, 1),
