(1821706, 249141, 34759, '<td valign="top">Awww, very nice capture! Seems a little washed out, but I''m guessing that''s because it''s a close crop. Nice job regardless!</td>', 'Awww, very nice capture! Seems a little washed out, but I''m guessing that''s because it''s a close crop. Nice job regardless!', '2005-10-28 18:40:07.000000', NULL, 1),
(1821714, 248473, 34759, '<td valign="top">Beautiful bird and photo, but the plants in the background seem a little overpowering, which distracts from the bird.</td>', 'Beautiful bird and photo, but the plants in the background seem a little overpowering, which distracts from the bird.', '2005-10-28 18:41:47.000000', NULL, 1),
(1821717, 249224, 34759, '<td valign="top">I think this would have been improved if you had cropped it a little bit lower. I really like it, but that top left corner of blown out sky pulls the eye upward and away from the pretty path, which to me is the appealing part of the photo.</td>', 'I think this would have been improved if you had cropped it a little bit lower. I really like it, but that top left corner of blown out sky pulls the eye upward and away from the pretty path, which to me is the appealing part of the photo.', '2005-10-28 18:43:37.000000', NULL, 1),
(1821721, 246706, 34759, '<td valign="top">I like this a lot. I love how part of the scene is dark under the shadows of the cloud and part has sunlight shining on it.</td>', 'I like this a lot. I love how part of the scene is dark under the shadows of the cloud and part has sunlight shining on it.', '2005-10-28 18:45:17.000000', NULL, 1),
