(1821929, 248593, 42198, '<td valign="top">What does it say? ''opicko''? ''chiko''?... Interesting composition, but I just can''t read what that message is! I''ll check back later and might see something. Update: This is driving me mad! - The first letter looks like ''c'', then ''p'', then ''i'' then ''k'', then ''e''... but that doesn''t spell anything!</td>', 'What does it say? ''opicko''? ''chiko''?... Interesting composition, but I just can''t read what that message is! I''ll check back later and might see something. Update: This is driving me mad! - The first letter looks like ''c'', then ''p'', then ''i'' then ''k'', then ''e''... but that doesn''t spell anything!', '2005-10-28 21:07:44.000000', NULL, 1),
(1821930, 248780, 42198, '<td valign="top">Very overprocessed. Looks like you have problems with jpg artifacts and sharpening here. Also there are shadows and it''s very centered. Interesting subject though.</td>', 'Very overprocessed. Looks like you have problems with jpg artifacts and sharpening here. Also there are shadows and it''s very centered. Interesting subject though.', '2005-10-28 21:10:07.000000', NULL, 1),
(1821933, 246715, 42198, '<td valign="top">Can''t see anything in sharp focus here. I think that''s a rose in the foreground. If that is the main subject, then it should be in focus.</td>', 'Can''t see anything in sharp focus here. I think that''s a rose in the foreground. If that is the main subject, then it should be in focus.', '2005-10-28 21:11:13.000000', NULL, 1),
(1821935, 249563, 42198, '<td valign="top">Too small. Pity, as the shot looks interesting.</td>', 'Too small. Pity, as the shot looks interesting.', '2005-10-28 21:11:33.000000', NULL, 1),
(1821937, 249137, 42198, '<td valign="top">Get rid of the date/time - looks very amateur with that in the corner. No main subject here, and not a very interesting landscape shot. Horizon isn''t level. I''m sorry I can''t find many nice things to say about this! - But I''m just giving my honest opinion.</td>', 'Get rid of the date/time - looks very amateur with that in the corner. No main subject here, and not a very interesting landscape shot. Horizon isn''t level. I''m sorry I can''t find many nice things to say about this! - But I''m just giving my honest opinion.', '2005-10-28 21:13:04.000000', NULL, 1),
(1821939, 249224, 42198, '<td valign="top">Nice shot. Very colourful. But I can''t really see the interpretation of ''delicate'' here.</td>', 'Nice shot. Very colourful. But I can''t really see the interpretation of ''delicate'' here.', '2005-10-28 21:14:05.000000', NULL, 1),
(1821942, 248928, 42198, '<td valign="top">Very noisy shot. Try Neat Image to get rid of that ISO noise. Apart from that, there''s no main point of interest. Can''t see the ''delicate'' connection either.</td>', 'Very noisy shot. Try Neat Image to get rid of that ISO noise. Apart from that, there''s no main point of interest. Can''t see the ''delicate'' connection either.', '2005-10-28 21:16:02.000000', NULL, 1),
(1821943, 248341, 45928, '<td valign="top">If this picture were bigger I could rate it much higher!</td>', 'If this picture were bigger I could rate it much higher!', '2005-10-28 21:17:08.000000', NULL, 1),
(1821944, 248449, 42198, '<td valign="top">He''s not really asleep, is he? :)</td>', 'He''s not really asleep, is he? :)', '2005-10-28 21:17:28.000000', NULL, 1),
(1821946, 247588, 40386, '<td valign="top">The harsh light and lack of focus spoils this shot, also it is not a Monarch Butterfly.</td>', 'The harsh light and lack of focus spoils this shot, also it is not a Monarch Butterfly.', '2005-10-28 21:17:52.000000', NULL, 1),
(1821948, 249587, 40386, '<td valign="top">Cute shot, I would have removed some of the yellow cast though.</td>', 'Cute shot, I would have removed some of the yellow cast though.', '2005-10-28 21:18:31.000000', NULL, 1),
(1821949, 248929, 45928, '<td valign="top">Fantastic, it almost looks like some sort of maze. I love the angle, the color, everything. Great idea!</td>', 'Fantastic, it almost looks like some sort of maze. I love the angle, the color, everything. Great idea!', '2005-10-28 21:18:33.000000', NULL, 1),
(1821950, 247925, 42198, '<td valign="top">Lighting is very harsh. Colours are a bit washed out as a result. But interesting composition though, shooting through the grass like that.</td>', 'Lighting is very harsh. Colours are a bit washed out as a result. But interesting composition though, shooting through the grass like that.', '2005-10-28 21:19:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1821953, 246715, 40386, '<td valign="top">This shot is out of focus.  If you had stepped back and shot the flower then cropped it in Photo editing package to exclude all the clutter around it It could have been a better shot.</td>', 'This shot is out of focus.  If you had stepped back and shot the flower then cropped it in Photo editing package to exclude all the clutter around it It could have been a better shot.', '2005-10-28 21:20:26.000000', NULL, 1),
(1821954, 249587, 46235, '<td valign="top">Wonderful picture!</td>', 'Wonderful picture!', '2005-10-28 21:20:53.000000', NULL, 1),
(1821955, 247595, 45928, '<td valign="top">I wish the hue had not been altered so much.</td>', 'I wish the hue had not been altered so much.', '2005-10-28 21:21:02.000000', NULL, 1),
(1821957, 247215, 42198, '<td valign="top">I love evocative shots like this. A remarkable composition. I actually find it quite disturbing! That crop just below her eyes ... in fact the whole way it''s cropped, the strange lighting, that dark background and the pose/expression (what we can see of it) just adds to the edgy feel of the image. Excellent!</td>', 'I love evocative shots like this. A remarkable composition. I actually find it quite disturbing! That crop just below her eyes ... in fact the whole way it''s cropped, the strange lighting, that dark background and the pose/expression (what we can see of it) just adds to the edgy feel of the image. Excellent!', '2005-10-28 21:22:35.000000', NULL, 1),
(1821959, 248283, 42198, '<td valign="top">Nicely done (no pun intended)</td>', 'Nicely done (no pun intended)', '2005-10-28 21:23:21.000000', NULL, 1),
(1821961, 249553, 45928, '<td valign="top">Great depth of field and color. The fact that the background is so out of focous really makes the shot.</td>', 'Great depth of field and color. The fact that the background is so out of focous really makes the shot.', '2005-10-28 21:23:59.000000', NULL, 1),
(1821969, 248341, 40386, '<td valign="top">I wish you had posted this larger.  It would have had a lot more impact.</td>', 'I wish you had posted this larger.  It would have had a lot more impact.', '2005-10-28 21:29:04.000000', NULL, 1),
(1821973, 248993, 46235, '<td valign="top">Great photo!  I love the composition and it really fits the theme!</td>', 'Great photo!  I love the composition and it really fits the theme!', '2005-10-28 21:30:27.000000', NULL, 1),
(1821991, 249133, 46235, '<td valign="top">Fantastic!  Beautiful color, great composition!</td>', 'Fantastic!  Beautiful color, great composition!', '2005-10-28 21:39:24.000000', NULL, 1),
