(1822995, 249268, 18339, '<td valign="top">Awe! She is so sweet looking.  Great shot but looks a bit off in color tone. I know not everyone here has photo shop so I won''t deduct for that.  Very delicate 6</td>', 'Awe! She is so sweet looking.  Great shot but looks a bit off in color tone. I know not everyone here has photo shop so I won''t deduct for that.  Very delicate 6', '2005-10-29 12:29:41.000000', NULL, 1),
(1822998, 247252, 18339, '<td valign="top">Is it a leaf in the river?  A delicate position to be in. Love the movement and drama of the color.</td>', 'Is it a leaf in the river?  A delicate position to be in. Love the movement and drama of the color.', '2005-10-29 12:31:28.000000', NULL, 1),
(1823022, 249563, 44944, '<td valign="top">Consider to make the photo larger. It is more inviting to look at and gives the opportunity to see details.</td>', 'Consider to make the photo larger. It is more inviting to look at and gives the opportunity to see details.', '2005-10-29 12:40:28.000000', NULL, 1),
(1823026, 249568, 44944, '<td valign="top">A pity of the color cast  on the girl''s right cheek/jaw line.</td>', 'A pity of the color cast  on the girl''s right cheek/jaw line.', '2005-10-29 12:43:04.000000', NULL, 1),
