INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1823113, 248433, 40295, '<td valign="top">I end up puzzeld by the flat area to the left - a pool of water??? Think a crop at the left edge of the bush on the left would have be more appealing. You might have to crop just a bit off the right to keep the balance, but keep the ferns there - they add to the challenge topic.</td>', 'I end up puzzeld by the flat area to the left - a pool of water??? Think a crop at the left edge of the bush on the left would have be more appealing. You might have to crop just a bit off the right to keep the balance, but keep the ferns there - they add to the challenge topic.', '2005-10-29 13:57:24.000000', NULL, 1),
