(1824748, 247215, 46902, '<td valign="top">Interesting concept. Raw. 10 for originality.</td>', 'Interesting concept. Raw. 10 for originality.', '2005-10-30 13:00:18.000000', NULL, 1),
(1824751, 249066, 33672, '<td valign="top">Nice shot. Interesting DOF, Lengthy title.</td>', 'Nice shot. Interesting DOF, Lengthy title.', '2005-10-30 13:04:37.000000', NULL, 1),
(1824752, 248274, 33672, '<td valign="top">Interesting but a little busy. Needs a bit of sharpening or so it seems.  Just my opinion...</td>', 'Interesting but a little busy. Needs a bit of sharpening or so it seems.  Just my opinion...', '2005-10-30 13:05:44.000000', NULL, 1),
(1824754, 249224, 46902, '<td valign="top">Nice walk home!</td>', 'Nice walk home!', '2005-10-30 13:06:25.000000', NULL, 1),
(1824755, 248881, 33672, '<td valign="top">Great example of the theme. Great comp and use of negative space.</td>', 'Great example of the theme. Great comp and use of negative space.', '2005-10-30 13:06:53.000000', NULL, 1),
(1824756, 249460, 33672, '<td valign="top">Nice comp, very emotive.</td>', 'Nice comp, very emotive.', '2005-10-30 13:07:19.000000', NULL, 1),
