(1824763, 248473, 33672, '<td valign="top">Well composed and shot.  Muddy water''s a distraction (color takes away from the contrast but I have no suggestions... Maybe try B&amp;W) Nice and sharp.</td>', 'Well composed and shot.  Muddy water''s a distraction (color takes away from the contrast but I have no suggestions... Maybe try B&W) Nice and sharp.', '2005-10-30 13:09:19.000000', NULL, 1),
(1824766, 246493, 33672, '<td valign="top">Lack of contrast in background colors takes away from the photo...Model has unique look.</td>', 'Lack of contrast in background colors takes away from the photo...Model has unique look.', '2005-10-30 13:11:58.000000', NULL, 1),
(1824771, 247836, 46902, '<td valign="top">Interesting effect</td>', 'Interesting effect', '2005-10-30 13:16:33.000000', NULL, 1),
