(1824778, 249592, 46904, '<td valign="top">Aahhh. Very nice. very good light angle. Careful inspection of the center of the flower absolutely conveys "delicate".</td>', 'Aahhh. Very nice. very good light angle. Careful inspection of the center of the flower absolutely conveys "delicate".', '2005-10-30 13:19:46.000000', NULL, 1),
(1824781, 247495, 46904, '<td valign="top">I would recommend a tighter crop? Too much of the image is out of focus, IMHO. The in-focus parts are magnificent, though. good job.</td>', 'I would recommend a tighter crop? Too much of the image is out of focus, IMHO. The in-focus parts are magnificent, though. good job.', '2005-10-30 13:21:09.000000', NULL, 1),
(1824782, 248593, 44011, '<td valign="top">I can''t tell what that is, but if it''s a reflection on water then it''s an amazing shot!</td>', 'I can''t tell what that is, but if it''s a reflection on water then it''s an amazing shot!', '2005-10-30 13:21:31.000000', NULL, 1),
(1824784, 247976, 46904, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2005-10-30 13:22:57.000000', NULL, 1),
(1824787, 247157, 46904, '<td valign="top">Is that a deliberate soft-focus effect? I feel that too much of the image is out of focus.</td>', 'Is that a deliberate soft-focus effect? I feel that too much of the image is out of focus.', '2005-10-30 13:25:39.000000', NULL, 1),
(1824790, 247588, 46904, '<td valign="top">Original crop. Cool light and colors.</td>', 'Original crop. Cool light and colors.', '2005-10-30 13:26:36.000000', NULL, 1),
(1824791, 249133, 46902, '<td valign="top">Nice light, great texture and lines</td>', 'Nice light, great texture and lines', '2005-10-30 13:26:48.000000', NULL, 1),
