(1824803, 249533, 46904, '<td valign="top">Very interesting take on the challenge. Nice execution too.</td>', 'Very interesting take on the challenge. Nice execution too.', '2005-10-30 13:33:56.000000', NULL, 1),
(1824808, 249327, 46902, '<td valign="top">Nice abstract. Fantastic colors.</td>', 'Nice abstract. Fantastic colors.', '2005-10-30 13:35:28.000000', NULL, 1),
