(1824828, 249066, 46902, '<td valign="top">Cute...</td>', 'Cute...', '2005-10-30 13:43:45.000000', NULL, 1),
(1824843, 249592, 45533, '<td valign="top">This is...breathtaking beyond works.</td>', 'This is...breathtaking beyond works.', '2005-10-30 13:57:53.000000', NULL, 1),
(1824845, 248383, 45533, '<td valign="top">This is amazing, wonderful photo.</td>', 'This is amazing, wonderful photo.', '2005-10-30 13:58:35.000000', NULL, 1),
(1824947, 249226, 5112, '<td valign="top">Very interesting choice for delicate, not what someone might think of immediately, but it works, and well.  Love the soft mood of the picture, even though it has so much "angularity" (can''t think of a better word right now).  No pure white, and probably no (or just minimal) pure black, yet it works.  I''m curious, what time of day did you make this picture?  The sky looks clear.  The branch in front looks like a scorpion.  Love it.</td>', 'Very interesting choice for delicate, not what someone might think of immediately, but it works, and well.  Love the soft mood of the picture, even though it has so much "angularity" (can''t think of a better word right now).  No pure white, and probably no (or just minimal) pure black, yet it works.  I''m curious, what time of day did you make this picture?  The sky looks clear.  The branch in front looks like a scorpion.  Love it.', '2005-10-30 15:57:19.000000', NULL, 1),
(1825043, 248929, 45587, '<td valign="top">Great colours.  What is it? :-)</td>', 'Great colours.  What is it? :-)', '2005-10-30 17:04:57.000000', NULL, 1),
(1825048, 249516, 35444, '<td valign="top">I wish I could give this photo more than a 10... beautifully done!</td>', 'I wish I could give this photo more than a 10... beautifully done!', '2005-10-30 17:11:47.000000', NULL, 1),
(1825049, 249434, 34013, '<td valign="top">wow. gorgeous image.</td>', 'wow. gorgeous image.', '2005-10-30 17:12:55.000000', NULL, 1),
(1825056, 249613, 35444, '<td valign="top">I love the lighting on this and the composition - everything is so well done!   A 10.</td>', 'I love the lighting on this and the composition - everything is so well done!   A 10.', '2005-10-30 17:19:04.000000', NULL, 1),
(1825058, 249124, 35444, '<td valign="top">Wow.  What a capture!  I love it - a praying mantis!  Excellent. 10.</td>', 'Wow.  What a capture!  I love it - a praying mantis!  Excellent. 10.', '2005-10-30 17:20:36.000000', NULL, 1),
