(1825064, 248057, 35444, '<td valign="top">Great lighting, attitude, posture.  Could be high fashion.</td>', 'Great lighting, attitude, posture.  Could be high fashion.', '2005-10-30 17:22:47.000000', NULL, 1),
(1825068, 247061, 35444, '<td valign="top">Great capture.  I love the perspective.</td>', 'Great capture.  I love the perspective.', '2005-10-30 17:24:19.000000', NULL, 1),
(1825099, 249549, 45933, '<td valign="top">beautiful!  The seed pods look as smooth as silk.  I love the textures and colors that are incorporated in this photo.  The focus hits it on the spot.</td>', 'beautiful!  The seed pods look as smooth as silk.  I love the textures and colors that are incorporated in this photo.  The focus hits it on the spot.', '2005-10-30 17:43:38.000000', NULL, 1),
(1825106, 249374, 45933, '<td valign="top">this is a touching photo.  you were able to grasp the delicate emotions in this scene.  I wish you could have not centered the subjects.</td>', 'this is a touching photo.  you were able to grasp the delicate emotions in this scene.  I wish you could have not centered the subjects.', '2005-10-30 17:46:02.000000', NULL, 1),
(1825111, 249192, 45933, '<td valign="top">wow. i''m impressed.  this is so abstract - i love the shapes and simple colors.  its beautiful.  looks like a painting.</td>', 'wow. i''m impressed.  this is so abstract - i love the shapes and simple colors.  its beautiful.  looks like a painting.', '2005-10-30 17:48:08.000000', NULL, 1),
(1825116, 247848, 45933, '<td valign="top">very interesting.  I am strongly attracted to the pastel-like colors.  The subject is positioned well in the photo.  The expression on the boy''s face adds a nice touch.</td>', 'very interesting.  I am strongly attracted to the pastel-like colors.  The subject is positioned well in the photo.  The expression on the boy''s face adds a nice touch.', '2005-10-30 17:50:08.000000', NULL, 1),
(1825120, 249268, 45933, '<td valign="top">how adorable.  i love the softness and natural expressions of young ones.  I wish you could have focused a bit more on the girl''s eye lashes, not hair.</td>', 'how adorable.  i love the softness and natural expressions of young ones.  I wish you could have focused a bit more on the girl''s eye lashes, not hair.', '2005-10-30 17:51:31.000000', NULL, 1),
(1825123, 249516, 45933, '<td valign="top">WOW. the colors blow me away.  The textures are just amazing.  I absolutely love how the red hair is brought up against the gray background.</td>', 'WOW. the colors blow me away.  The textures are just amazing.  I absolutely love how the red hair is brought up against the gray background.', '2005-10-30 17:53:49.000000', NULL, 1),
(1825130, 249124, 45933, '<td valign="top">This is sooooo cute!!!  I Love the simplicity of this photo.  The praying mantis'' eye really catches me.</td>', 'This is sooooo cute!!!  I Love the simplicity of this photo.  The praying mantis'' eye really catches me.', '2005-10-30 17:55:13.000000', NULL, 1),
(1825135, 249197, 45933, '<td valign="top">This photo is too simple for my taste.  I wish you could have focused much more on the subject.</td>', 'This photo is too simple for my taste.  I wish you could have focused much more on the subject.', '2005-10-30 17:56:22.000000', NULL, 1),
(1825139, 249587, 45933, '<td valign="top">Wow. i am astounded with the warm glow of this child''s face.  Her eyes are spectacular.   You have done a great job with focus.</td>', 'Wow. i am astounded with the warm glow of this child''s face.  Her eyes are spectacular.   You have done a great job with focus.', '2005-10-30 17:57:45.000000', NULL, 1),
(1825143, 247724, 32754, '<td valign="top">Lovely image..graphic and beautiful and delicate..well done, excellent clarity and composition.</td>', 'Lovely image..graphic and beautiful and delicate..well done, excellent clarity and composition.', '2005-10-30 17:59:25.000000', NULL, 1),
(1825145, 248383, 45933, '<td valign="top">Oh my goodness...This is a spider?? I cannot believe my eyes.  You have captured a magnificent photo.  The background shades are nice, as well as the focus of the subject.  I especially love how the water droplets on the legs captured reflections of the scenery.</td>', 'Oh my goodness...This is a spider?? I cannot believe my eyes.  You have captured a magnificent photo.  The background shades are nice, as well as the focus of the subject.  I especially love how the water droplets on the legs captured reflections of the scenery.', '2005-10-30 18:00:21.000000', NULL, 1),
(1825147, 248551, 32754, '<td valign="top">lovely image and composition..back for another view..dof is right on...  soft and appealing.</td>', 'lovely image and composition..back for another view..dof is right on...  soft and appealing.', '2005-10-30 18:00:39.000000', NULL, 1),
(1825151, 248243, 45933, '<td valign="top">Wow. the brilliant patterns and colors of the butterfly are amazing.  I believe this photo is composed a bit too simply.  Good job with not centering the subject!</td>', 'Wow. the brilliant patterns and colors of the butterfly are amazing.  I believe this photo is composed a bit too simply.  Good job with not centering the subject!', '2005-10-30 18:03:15.000000', NULL, 1),
