INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1827134, 248600, 28471, '<td valign="top">I appreciate the effect you were going for here but I think the overall image qulaity suffered as a result.  The grain and blur are just too distracting.</td>', 'I appreciate the effect you were going for here but I think the overall image qulaity suffered as a result.  The grain and blur are just too distracting.', '2005-10-31 13:51:46.000000', NULL, 1),
(1827174, 249160, 30669, '<td valign="top">Awesome ! 9</td>', 'Awesome ! 9', '2005-10-31 14:08:35.000000', NULL, 1),
(1827247, 249391, 14805, '<td valign="top">should be more sharp</td>', 'should be more sharp', '2005-10-31 14:30:08.000000', NULL, 1),
(1827310, 249553, 35122, '<td valign="top">Gorgeous!!!!!  10   10   10   10</td>', 'Gorgeous!!!!!  10   10   10   10', '2005-10-31 14:47:43.000000', NULL, 1),
(1827335, 248987, 40019, '<td valign="top">Love the rich colors!  Good focus.  "Delicate" and frogs just don''t go together for me. &lt;5&gt;</td>', 'Love the rich colors!  Good focus.  "Delicate" and frogs just don''t go together for me. <5>', '2005-10-31 14:54:17.000000', NULL, 1),
(1827340, 248350, 40019, '<td valign="top">Great capture!  It''s usually pretty hard to get this kind of crispness through water. Nicely done!  (Must have just cleaned the tank.)  :-)</td>', 'Great capture!  It''s usually pretty hard to get this kind of crispness through water. Nicely done!  (Must have just cleaned the tank.)  :-)', '2005-10-31 14:55:26.000000', NULL, 1),
(1827344, 249467, 40019, '<td valign="top">Great detail and color!  Really gives the feeling of being delicate!</td>', 'Great detail and color!  Really gives the feeling of being delicate!', '2005-10-31 14:56:20.000000', NULL, 1),
(1827350, 248057, 40019, '<td valign="top">17 is a delicate age, but her expression, pose and attire are far from "delicate" IMO.  I like the back lighting and composition though. &lt;5&gt;</td>', '17 is a delicate age, but her expression, pose and attire are far from "delicate" IMO.  I like the back lighting and composition though. <5>', '2005-10-31 14:58:07.000000', NULL, 1),
(1827379, 246849, 10134, '<td valign="top">don''t touch me ?</td>', 'don''t touch me ?', '2005-10-31 15:13:19.000000', NULL, 1),
(1827390, 248057, 40667, '<td valign="top">nice shot, it seems posed, but natural, and i think thats what you were going for!</td>', 'nice shot, it seems posed, but natural, and i think thats what you were going for!', '2005-10-31 15:17:44.000000', NULL, 1),
(1827393, 249391, 43434, '<td valign="top">a little centred .. but a lovely depiction</td>', 'a little centred .. but a lovely depiction', '2005-10-31 15:17:56.000000', NULL, 1),
(1827399, 248560, 43434, '<td valign="top">The photo feels very centred ... lovely wee girl though</td>', 'The photo feels very centred ... lovely wee girl though', '2005-10-31 15:19:54.000000', NULL, 1),
(1827419, 249516, 44268, '<td valign="top">Great shot! This photo just screams ''delicate''. I can''t help thinking the dress is overexposed, though. Added to favorites.</td>', 'Great shot! This photo just screams ''delicate''. I can''t help thinking the dress is overexposed, though. Added to favorites.', '2005-10-31 15:26:47.000000', NULL, 1),
(1827453, 248593, 40019, '<td valign="top">Wow!  What a cool picture!  Too bad you didn''t have this for the Reflections challenge!</td>', 'Wow!  What a cool picture!  Too bad you didn''t have this for the Reflections challenge!', '2005-10-31 15:48:34.000000', NULL, 1),
(1827457, 248497, 40019, '<td valign="top">Great tonal quality, nicely done.</td>', 'Great tonal quality, nicely done.', '2005-10-31 15:49:10.000000', NULL, 1),
(1827460, 248856, 40019, '<td valign="top">Beautiful picture!  Very warm feeling.</td>', 'Beautiful picture!  Very warm feeling.', '2005-10-31 15:50:17.000000', NULL, 1),
(1827477, 246925, 40019, '<td valign="top">Great colors!  Would have loved to have the body in better focus.  It appears you had the focus set for the flower just in front of the butterfly.  I greater DOF may have helped.</td>', 'Great colors!  Would have loved to have the body in better focus.  It appears you had the focus set for the flower just in front of the butterfly.  I greater DOF may have helped.', '2005-10-31 15:55:40.000000', NULL, 1),
(1827479, 248551, 40019, '<td valign="top">Wow, this would have been a great "Textures" challenge entry as well - I can almost feel the  softness.  Nicely done!</td>', 'Wow, this would have been a great "Textures" challenge entry as well - I can almost feel the  softness.  Nicely done!', '2005-10-31 15:56:27.000000', NULL, 1),
(1827480, 249313, 40019, '<td valign="top">I love Granny''s expression.  I would have liked to see better focus, especially on the eyes - they usually tell the story.</td>', 'I love Granny''s expression.  I would have liked to see better focus, especially on the eyes - they usually tell the story.', '2005-10-31 15:57:33.000000', NULL, 1),
(1827523, 249533, 40019, '<td valign="top">Wow, incredible image! Lighting and textures are perfect.</td>', 'Wow, incredible image! Lighting and textures are perfect.', '2005-10-31 16:22:42.000000', NULL, 1),
(1827526, 247146, 40019, '<td valign="top">Would have made for an interesting "Shutter Speed" challenge entry as well.  Good lighting and textures.</td>', 'Would have made for an interesting "Shutter Speed" challenge entry as well.  Good lighting and textures.', '2005-10-31 16:23:55.000000', NULL, 1),
(1827527, 248354, 40019, '<td valign="top">The ant makes the picture!</td>', 'The ant makes the picture!', '2005-10-31 16:24:22.000000', NULL, 1),
(1827530, 246513, 40019, '<td valign="top">Nicely done.  I like the colors and border - it''s different.</td>', 'Nicely done.  I like the colors and border - it''s different.', '2005-10-31 16:25:10.000000', NULL, 1),
(1827532, 248722, 32644, '<td valign="top">Sorry, I don''t get it. Maybe better lighting would help get your message across?</td>', 'Sorry, I don''t get it. Maybe better lighting would help get your message across?', '2005-10-31 16:25:31.000000', NULL, 1),
(1827536, 249241, 40019, '<td valign="top">Nice statement - great tonal qualities - great capture!</td>', 'Nice statement - great tonal qualities - great capture!', '2005-10-31 16:26:13.000000', NULL, 1),
(1827537, 247921, 32644, '<td valign="top">reallly?</td>', 'reallly?', '2005-10-31 16:26:15.000000', NULL, 1),
(1827551, 248812, 40019, '<td valign="top">Yes they are, but they''re not looking too delicate here - especially with the facial expression on the girl in green.  Nice sport action capture, but I''m not getting the "delicate" feeling from this picture.  &lt;5&gt;</td>', 'Yes they are, but they''re not looking too delicate here - especially with the facial expression on the girl in green.  Nice sport action capture, but I''m not getting the "delicate" feeling from this picture.  <5>', '2005-10-31 16:29:15.000000', NULL, 1),
(1827556, 249321, 40019, '<td valign="top">Good theme.  A couple of feet peeking out from the edge of the covers would have really made the shot for me.</td>', 'Good theme.  A couple of feet peeking out from the edge of the covers would have really made the shot for me.', '2005-10-31 16:30:35.000000', NULL, 1),
(1827559, 248318, 40019, '<td valign="top">Great capture!  Poor little guy looks like he''s barely hanging on.  :-)</td>', 'Great capture!  Poor little guy looks like he''s barely hanging on.  :-)', '2005-10-31 16:31:22.000000', NULL, 1),
(1827562, 249587, 40019, '<td valign="top">Wonderful picture!  I really like the clarity of the eyes.  Great texture.</td>', 'Wonderful picture!  I really like the clarity of the eyes.  Great texture.', '2005-10-31 16:32:17.000000', NULL, 1),
(1827566, 249280, 40019, '<td valign="top">Great capture!  So delicate, looks like a strong wind could shatter it.  Nicely done!</td>', 'Great capture!  So delicate, looks like a strong wind could shatter it.  Nicely done!', '2005-10-31 16:33:26.000000', NULL, 1),
(1827567, 247495, 40019, '<td valign="top">Great macro!  Nicely done.  I love the colors and clarity.</td>', 'Great macro!  Nicely done.  I love the colors and clarity.', '2005-10-31 16:34:37.000000', NULL, 1),
(1827569, 249262, 32644, '<td valign="top">It''s hard to tell if the ring is damaged or not. The highlights blow out the detail.<br/>Clever idea though.</td>', 'It''s hard to tell if the ring is damaged or not. The highlights blow out the detail.Clever idea though.', '2005-10-31 16:34:48.000000', NULL, 1),
(1827571, 248361, 32644, '<td valign="top">Yes, it is tiny but too dark to see very well.</td>', 'Yes, it is tiny but too dark to see very well.', '2005-10-31 16:35:45.000000', NULL, 1),
(1827574, 248984, 32644, '<td valign="top">This is a beautiful rose. It just isn''t sharp enough. Looks handheld at too slow a shutter speed. Maybe a tripod would have helped.</td>', 'This is a beautiful rose. It just isn''t sharp enough. Looks handheld at too slow a shutter speed. Maybe a tripod would have helped.', '2005-10-31 16:37:30.000000', NULL, 1),
(1827575, 249580, 32644, '<td valign="top">I like this idea. I don''t like the lighting - too dark. The yolk looks almost too orange.</td>', 'I like this idea. I don''t like the lighting - too dark. The yolk looks almost too orange.', '2005-10-31 16:39:02.000000', NULL, 1),
(1827578, 248341, 32644, '<td valign="top">This is a beautiful picture. Unfortunately it is too small. If it had been sized correctly for the challenge, I would have given it high marks. Please try again - you seem to have a good eye.</td>', 'This is a beautiful picture. Unfortunately it is too small. If it had been sized correctly for the challenge, I would have given it high marks. Please try again - you seem to have a good eye.', '2005-10-31 16:41:02.000000', NULL, 1),
(1827581, 249124, 40019, '<td valign="top">Great capture.  The flower itself would have been a nice "delicate" entry, but the juxtaposition of the young praying mantis on the soft peddles really made the shot. Great find!</td>', 'Great capture.  The flower itself would have been a nice "delicate" entry, but the juxtaposition of the young praying mantis on the soft peddles really made the shot. Great find!', '2005-10-31 16:42:46.000000', NULL, 1),
(1827583, 248214, 32644, '<td valign="top">Overall picture is way too dark to be attractive to me. :( Good idea but it is hard to see what the bird is perched on.</td>', 'Overall picture is way too dark to be attractive to me. :( Good idea but it is hard to see what the bird is perched on.', '2005-10-31 16:43:04.000000', NULL, 1),
(1827585, 249568, 40019, '<td valign="top">Nice composition and textures.</td>', 'Nice composition and textures.', '2005-10-31 16:43:08.000000', NULL, 1),
(1827587, 249553, 9671, '<td valign="top">very delicate  the bokeh above the flower is great, maybe a different crop could make it even better</td>', 'very delicate  the bokeh above the flower is great, maybe a different crop could make it even better', '2005-10-31 16:44:27.000000', NULL, 1),
(1827590, 249124, 32644, '<td valign="top">Beautiful DOF. Very interesting critter. It probably looked good with a greater DOF too. I can  barely make out the water drops on the rose.</td>', 'Beautiful DOF. Very interesting critter. It probably looked good with a greater DOF too. I can  barely make out the water drops on the rose.', '2005-10-31 16:45:02.000000', NULL, 1),
(1827592, 249160, 40019, '<td valign="top">Nice picture.  Looks a little too sharpened, or too much noise for me.  I would have liked a softer look with some saturated colors - would have provided a more "delicate" feeling for me. &lt;6&gt;</td>', 'Nice picture.  Looks a little too sharpened, or too much noise for me.  I would have liked a softer look with some saturated colors - would have provided a more "delicate" feeling for me. <6>', '2005-10-31 16:45:36.000000', NULL, 1),
(1827597, 249160, 32644, '<td valign="top">Beautiful shot! Perfect lighting, background, and DOF. A Winner!</td>', 'Beautiful shot! Perfect lighting, background, and DOF. A Winner!', '2005-10-31 16:46:12.000000', NULL, 1),
(1827602, 249521, 32644, '<td valign="top">Of all the milkweed shots, I liked this one the best.  The seeds are just on the verge of flying away. Good DOF too.;)</td>', 'Of all the milkweed shots, I liked this one the best.  The seeds are just on the verge of flying away. Good DOF too.;)', '2005-10-31 16:47:37.000000', NULL, 1),
(1827604, 249386, 40019, '<td valign="top">I get the theme, but I''m not sure if the picture really represents it that well.  It just looks like a crowd to me.  A picture juxtaposing a man and woman as equals in a competition or stand-off of some type would have better supported your title. IMO &lt;5&gt;</td>', 'I get the theme, but I''m not sure if the picture really represents it that well.  It just looks like a crowd to me.  A picture juxtaposing a man and woman as equals in a competition or stand-off of some type would have better supported your title. IMO <5>', '2005-10-31 16:48:37.000000', NULL, 1),
(1827606, 249563, 40019, '<td valign="top">Great picture!  I would have liked to see it larger though.</td>', 'Great picture!  I would have liked to see it larger though.', '2005-10-31 16:49:04.000000', NULL, 1),
(1827608, 248373, 40019, '<td valign="top">Nice capture.  The colors are a little muted though.</td>', 'Nice capture.  The colors are a little muted though.', '2005-10-31 16:49:35.000000', NULL, 1),
(1827613, 249533, 32644, '<td valign="top">I love this shot. The fingers look unnaturally long. How did you light this and what is in that egg?</td>', 'I love this shot. The fingers look unnaturally long. How did you light this and what is in that egg?', '2005-10-31 16:50:17.000000', NULL, 1),
(1827618, 248798, 40019, '<td valign="top">Wow, nice bold colors!  Almost too bold for a "delicate" theme.  I like the picture though! (Although the sky on the left corner looks a little fake.)</td>', 'Wow, nice bold colors!  Almost too bold for a "delicate" theme.  I like the picture though! (Although the sky on the left corner looks a little fake.)', '2005-10-31 16:50:54.000000', NULL, 1),
(1827621, 248473, 32644, '<td valign="top">This is very cool. Why is the water that color? It gives the bird a very nice glow.</td>', 'This is very cool. Why is the water that color? It gives the bird a very nice glow.', '2005-10-31 16:51:47.000000', NULL, 1),
(1827626, 248243, 32644, '<td valign="top">Awwww. Beautiful even after life.</td>', 'Awwww. Beautiful even after life.', '2005-10-31 16:52:38.000000', NULL, 1),
