(1827632, 249254, 32644, '<td valign="top">This is too funny. Great catch, framing and DOF.</td>', 'This is too funny. Great catch, framing and DOF.', '2005-10-31 16:54:44.000000', NULL, 1),
(1827639, 248350, 32644, '<td valign="top">Beautiful! Did you shoot this underwater? If not, I am very impressed.</td>', 'Beautiful! Did you shoot this underwater? If not, I am very impressed.', '2005-10-31 16:56:56.000000', NULL, 1),
(1827641, 248048, 32644, '<td valign="top">Very nice catch!</td>', 'Very nice catch!', '2005-10-31 16:57:40.000000', NULL, 1),
