(1829903, 247061, 41377, '<td valign="top">Great detail.</td>', 'Great detail.', '2005-11-01 13:23:40.000000', NULL, 1),
(1829906, 249391, 45790, '<td valign="top">Not as sharp as it could be.</td>', 'Not as sharp as it could be.', '2005-11-01 13:24:52.000000', NULL, 1),
