(1829947, 249297, 45802, '<td valign="top">The photo doesn''t give me a sense of the future.</td>', 'The photo doesn''t give me a sense of the future.', '2005-11-01 13:43:08.000000', NULL, 1),
(1829951, 248497, 45802, '<td valign="top">I like the photo; I hate the border (but I don''t judge it).</td>', 'I like the photo; I hate the border (but I don''t judge it).', '2005-11-01 13:45:15.000000', NULL, 1),
(1829954, 249574, 45802, '<td valign="top">I think cutting off the yellow on the right was a mistake.</td>', 'I think cutting off the yellow on the right was a mistake.', '2005-11-01 13:47:32.000000', NULL, 1),
(1829955, 249516, 23680, '<td valign="top">Outstanding - 10</td>', 'Outstanding - 10', '2005-11-01 13:48:03.000000', NULL, 1),
(1829961, 249467, 45802, '<td valign="top">Rotate left 90 degrees and it''s a very nice shot, otherwise it feels unbalanced.</td>', 'Rotate left 90 degrees and it''s a very nice shot, otherwise it feels unbalanced.', '2005-11-01 13:49:56.000000', NULL, 1),
(1829980, 249210, 45802, '<td valign="top">I think that if you crop out most of the left side, then you''d lose the very bright part of the sky, which is really distracting. Keep the right side of the flower and crop till the picture is symmetrical with the vertical axis through the flower stem.</td>', 'I think that if you crop out most of the left side, then you''d lose the very bright part of the sky, which is really distracting. Keep the right side of the flower and crop till the picture is symmetrical with the vertical axis through the flower stem.', '2005-11-01 13:59:17.000000', NULL, 1),
(1829989, 249395, 45802, '<td valign="top">There is too much power given to the dead space on the right.</td>', 'There is too much power given to the dead space on the right.', '2005-11-01 14:01:24.000000', NULL, 1),
(1830033, 249422, 42100, '<td valign="top">Nice crisp image, but centered composition doesn''t do much for the photo.</td>', 'Nice crisp image, but centered composition doesn''t do much for the photo.', '2005-11-01 14:16:50.000000', NULL, 1),
(1830036, 248274, 42100, '<td valign="top">Interesting subject, but the composition seems a bit busy.</td>', 'Interesting subject, but the composition seems a bit busy.', '2005-11-01 14:17:53.000000', NULL, 1),
(1830050, 249025, 42100, '<td valign="top">Interesting subject matter but compositionally no clear focal point.</td>', 'Interesting subject matter but compositionally no clear focal point.', '2005-11-01 14:20:53.000000', NULL, 1),
(1830075, 248928, 42100, '<td valign="top">Horizon at the 1/3 position is good, but compositionally the sun is just to overwhelming.</td>', 'Horizon at the 1/3 position is good, but compositionally the sun is just to overwhelming.', '2005-11-01 14:24:57.000000', NULL, 1),
(1830085, 249337, 39675, '<td valign="top">This is an excellent overal image.  It fits the challenge perfectly.  I love the depth of field with the lower petals out of focus creating a very soft and delicate backdrop, although I think you may be voted lower by some people, because they will not notice how sharp the center of the flower truely is.  The colors are great.  The center composition works well here because it draws you inside the bloom.  Again, excellent first photo.  I''ll rate it a 6.  -Czaja</td>', 'This is an excellent overal image.  It fits the challenge perfectly.  I love the depth of field with the lower petals out of focus creating a very soft and delicate backdrop, although I think you may be voted lower by some people, because they will not notice how sharp the center of the flower truely is.  The colors are great.  The center composition works well here because it draws you inside the bloom.  Again, excellent first photo.  I''ll rate it a 6.  -Czaja', '2005-11-01 14:26:28.000000', NULL, 1),
(1830099, 246849, 42100, '<td valign="top">Interesting pose by the model.  Good tight crop, maybe could be a little lower to include the thighs and elimate the empty space at top.  Backgound is too busy and detracts from the subject.</td>', 'Interesting pose by the model.  Good tight crop, maybe could be a little lower to include the thighs and elimate the empty space at top.  Backgound is too busy and detracts from the subject.', '2005-11-01 14:28:36.000000', NULL, 1),
(1830111, 249563, 42100, '<td valign="top">Perhaps moving the person to the right and including more of the horse would help balance out the photo a little better.</td>', 'Perhaps moving the person to the right and including more of the horse would help balance out the photo a little better.', '2005-11-01 14:31:24.000000', NULL, 1),
(1830117, 249281, 42100, '<td valign="top">Very good composition, except for the cat looking out of the picture.  It seems to lead the eye away from the photo.</td>', 'Very good composition, except for the cat looking out of the picture.  It seems to lead the eye away from the photo.', '2005-11-01 14:33:41.000000', NULL, 1),
(1830146, 249605, 47059, '<td valign="top">It'' har to tell what is in focus</td>', 'It'' har to tell what is in focus', '2005-11-01 14:43:27.000000', NULL, 1),
(1830147, 248009, 47059, '<td valign="top">Nice Contrasts</td>', 'Nice Contrasts', '2005-11-01 14:43:50.000000', NULL, 1),
(1830153, 249457, 47059, '<td valign="top">The right side of the photo is out of focus, but the direction of the lines in the photo has an appealing effect.  I also like the contrast of the moon in the background.</td>', 'The right side of the photo is out of focus, but the direction of the lines in the photo has an appealing effect.  I also like the contrast of the moon in the background.', '2005-11-01 14:45:35.000000', NULL, 1),
(1830155, 248593, 47059, '<td valign="top">Very Interesting...</td>', 'Very Interesting...', '2005-11-01 14:46:20.000000', NULL, 1),
(1830156, 248042, 47059, '<td valign="top">very nice.</td>', 'very nice.', '2005-11-01 14:46:58.000000', NULL, 1),
(1830159, 248928, 47059, '<td valign="top">I like the sunset/sunrise effect, but the glare from the water is too noisy.  Maybe soften it up a bit.</td>', 'I like the sunset/sunrise effect, but the glare from the water is too noisy.  Maybe soften it up a bit.', '2005-11-01 14:47:49.000000', NULL, 1),
(1830160, 247493, 47059, '<td valign="top">Very clean.  Nice colors.</td>', 'Very clean.  Nice colors.', '2005-11-01 14:48:08.000000', NULL, 1),
(1830164, 246827, 47059, '<td valign="top">Wow!  This does depict delicate.</td>', 'Wow!  This does depict delicate.', '2005-11-01 14:49:36.000000', NULL, 1),
(1830170, 249516, 47059, '<td valign="top">Beautiful!  I realy like the color contrasts, as well as the color matching!  It''s very intersting.  With the harshness of the background, you have a delicate little girl with tiny little toes.  But even further, you have a little girl holding a delicate little yellow flower.</td>', 'Beautiful!  I realy like the color contrasts, as well as the color matching!  It''s very intersting.  With the harshness of the background, you have a delicate little girl with tiny little toes.  But even further, you have a little girl holding a delicate little yellow flower.', '2005-11-01 14:52:54.000000', NULL, 1),
(1830173, 248984, 47059, '<td valign="top">out of focus</td>', 'out of focus', '2005-11-01 14:54:41.000000', NULL, 1),
(1830175, 247724, 47059, '<td valign="top">nice picuture, but it seems too monotone.</td>', 'nice picuture, but it seems too monotone.', '2005-11-01 14:55:11.000000', NULL, 1),
(1830189, 249568, 45929, '<td valign="top">I like the expression on her face, yet there is something off about the focus or sharpness.</td>', 'I like the expression on her face, yet there is something off about the focus or sharpness.', '2005-11-01 15:00:29.000000', NULL, 1),
(1830216, 249124, 45435, '<td valign="top">excellent.</td>', 'excellent.', '2005-11-01 15:17:44.000000', NULL, 1),
(1830222, 249361, 45435, '<td valign="top">nice photo and nice translation of delicate but I think the doll is distracting.</td>', 'nice photo and nice translation of delicate but I think the doll is distracting.', '2005-11-01 15:19:55.000000', NULL, 1),
(1830223, 249533, 45435, '<td valign="top">Finally...something original and done well. very nice</td>', 'Finally...something original and done well. very nice', '2005-11-01 15:21:23.000000', NULL, 1),
(1830233, 248798, 43869, '<td valign="top">Well this doesn''t necessarily say delicate to me, but we all have different views of delicate.  I LOVE the colors.  Beautiful shot!</td>', 'Well this doesn''t necessarily say delicate to me, but we all have different views of delicate.  I LOVE the colors.  Beautiful shot!', '2005-11-01 15:25:21.000000', NULL, 1),
(1830322, 248289, 33219, '<td valign="top">This is a lovely photo but it''s a shame the eyes aren''t in focus.</td>', 'This is a lovely photo but it''s a shame the eyes aren''t in focus.', '2005-11-01 16:03:54.000000', NULL, 1),
(1830352, 248830, 43031, '<td valign="top">perfect display of the stated emotion, so many emotive pictures just miss the mark, yours is spot on.</td>', 'perfect display of the stated emotion, so many emotive pictures just miss the mark, yours is spot on.', '2005-11-01 16:18:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1830354, 249521, 45934, '<td valign="top">I really like how the most delicate features of this particular plant is not focused in too much and just enough so that it creates that sense of delicacy.</td>', 'I really like how the most delicate features of this particular plant is not focused in too much and just enough so that it creates that sense of delicacy.', '2005-11-01 16:19:40.000000', NULL, 1),
