(1830360, 249549, 45934, '<td valign="top">I really like the clarity. Good Job!</td>', 'I really like the clarity. Good Job!', '2005-11-01 16:21:26.000000', NULL, 1),
(1830362, 246849, 43031, '<td valign="top">if you''re going fo delicate, then have the model act delicate. this exudes a position of feminine power and seduction. focus is off or you forgot to sharpen for web viewing, need an even background, or one that adds to the message.</td>', 'if you''re going fo delicate, then have the model act delicate. this exudes a position of feminine power and seduction. focus is off or you forgot to sharpen for web viewing, need an even background, or one that adds to the message.', '2005-11-01 16:22:27.000000', NULL, 1),
(1830363, 249574, 45934, '<td valign="top">I really like the clarity as well as the alignment of the flower ;)</td>', 'I really like the clarity as well as the alignment of the flower ;)', '2005-11-01 16:22:51.000000', NULL, 1),
(1830366, 249232, 45934, '<td valign="top">I dont really see how delicate ties in this particular picture...</td>', 'I dont really see how delicate ties in this particular picture...', '2005-11-01 16:23:29.000000', NULL, 1),
