(1830384, 249422, 43031, '<td valign="top">would have liked a tighter crop, and maybe the flower off-center. you could get rid of the whole left side and bottom, and have a much better photo I think.</td>', 'would have liked a tighter crop, and maybe the flower off-center. you could get rid of the whole left side and bottom, and have a much better photo I think.', '2005-11-01 16:31:21.000000', NULL, 1),
(1830389, 249529, 43031, '<td valign="top">background is distracting to me. like the light on the feather though.</td>', 'background is distracting to me. like the light on the feather though.', '2005-11-01 16:33:55.000000', NULL, 1),
(1830391, 248995, 43031, '<td valign="top">lovely colors and details, need to tone down the border a bit I think.</td>', 'lovely colors and details, need to tone down the border a bit I think.', '2005-11-01 16:35:20.000000', NULL, 1),
