(1830583, 247215, 22459, '<td valign="top">OK it''s strange but the nature of delicate is a clear message here. Dare to be different, I like that.</td>', 'OK it''s strange but the nature of delicate is a clear message here. Dare to be different, I like that.', '2005-11-01 17:45:48.000000', NULL, 1),
(1830585, 249539, 24991, '<td valign="top">Would have liked a little bit more DOF to get the entire Tiffany &amp; Co. in focus, good B&amp;W though, and I like your title.</td>', 'Would have liked a little bit more DOF to get the entire Tiffany & Co. in focus, good B&W though, and I like your title.', '2005-11-01 17:46:16.000000', NULL, 1),
